#!/usr/bin/env python3
"""Small original reactive sound patch; existing squeaks copied unchanged, no app edits."""
from pathlib import Path
import numpy as np
import struct,wave,json,hashlib,zipfile,shutil,math
R=Path(__file__).resolve().parents[1];B=Path('/workspace/motion-buddy-contact-audio-v1');SR=48000
for d in ['audio/app','audio/masters','src']:(R/d).mkdir(parents=True,exist_ok=True)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
records=[]
for key in ['pet_soft_squeak','pet_round_chirp','pet_content_wobble']:
    for folder,suffix in [('app','app_pcm16_48k'),('masters','master_f32_48k')]:
        src=B/f'audio/{folder}/{key}_{suffix}.wav';dst=R/f'audio/{folder}/{key}_{suffix}.wav';shutil.copyfile(src,dst);assert sha(src)==sha(dst)
    records.append({'key':key,'app':f'audio/app/{key}_app_pcm16_48k.wav','provenance':'Original previously delivered contact cue; copied byte-for-byte, not resynthesised.'})
shutil.copyfile(B/'src/create_playful_assets.py',R/'src/legacy_contact_generator_reference_only.py')
for key,dur,f0,f1 in [('pet_squish_press',.28,255,118),('pet_spring_release',.22,145,410)]:
    t=np.arange(round(dur*SR))/SR;ph=2*np.pi*(f0*t+.5*(f1-f0)*t*t/dur);env=np.sin(np.pi*t/dur)**1.3
    seed=137 if key.endswith('press') else 138;rng=np.random.default_rng(seed);raw=rng.normal(size=len(t));F=np.fft.rfft(raw);freq=np.fft.rfftfreq(len(t),1/SR);F*=np.exp(-(freq/650)**4);noise=np.fft.irfft(F,n=len(t));noise/=max(abs(noise))
    x=env*(np.sin(ph)+.08*np.sin(2*ph)+.18*noise);x-=x.mean();n=384;x[:n]*=np.linspace(0,1,n);x[-n:]*=np.linspace(1,0,n);x*=10**(-17/20)/max(abs(x));x[0]=x[-1]=0
    assert np.isfinite(x).all() and max(abs(x))<.15
    data=np.asarray(x,dtype='<f4').tobytes();master=R/f'audio/masters/{key}_master_f32_48k.wav';master.write_bytes(b'RIFF'+struct.pack('<I',36+len(data))+b'WAVEfmt '+struct.pack('<IHHIIHH',16,3,1,SR,SR*4,4,32)+b'data'+struct.pack('<I',len(data))+data)
    app=R/f'audio/app/{key}_app_pcm16_48k.wav';q=np.round(x*32767).astype('<i2')
    with wave.open(str(app),'wb') as w:w.setnchannels(1);w.setsampwidth(2);w.setframerate(SR);w.writeframes(q.tobytes())
    with wave.open(str(app),'rb') as w:assert (w.getnchannels(),w.getsampwidth(),w.getframerate(),w.getnframes())==(1,2,SR,len(x))
    y=q.astype(float)/32767;assert q[0]==q[-1]==0 and max(abs(y-x))<=1/32767
    records.append({'key':key,'app':str(app.relative_to(R)),'master':str(master.relative_to(R)),'seconds':len(x)/SR,'peak_dbfs':20*math.log10(max(abs(y))),'rms_dbfs':20*math.log10(np.sqrt(np.mean(y*y))),'loop':False,'provenance':'New original mathematical/filtered-noise sound, no samples or voice.'})
reactions={'coordinate_space':'Existing face transform only; no new face or costume. Numbers are small creative targets for Code to adapt to current bounded transforms, not runtime acceptance.','touch':{'tap_boop':{'seconds':.42,'scale_keyframes':[[0,1,1],[.10,1.09,.90],[.25,.97,1.03],[.42,1,1]],'sound':'Choose ONE existing short squeak/chirp.'},'pet_squish':{'while_contact':'Ease towards scaleX1.15/scaleY.83 (bounded), tiny +/-2deg wobble only as finger moves. Preserve rounded white eyes and tiny mouth.','release_seconds':.48,'release_scale_keyframes':[[0,1.15,.83],[.16,.96,1.06],[.30,1.03,.98],[.48,1,1]],'sound':'Choose press OR spring-release as the single sound for this gesture, not both.'},'finger_follow':{'behavior':'Keep existing gaze tracking for finger on/around Buddy; allow small whole-face lean within existing safe bounds on the follow variant. Do not silently replace petting with follow-only. Give both predictable access (tap vs pet/drag or existing gesture routing).','sound':'At most ONE short nonrepeating alternative for gesture; visual tracking can stay continuous without audio.'}},'car_reaction_ideas':{'acceleration':{'scaleX':.94,'scaleY':1.06,'translateY_face_units':5},'brake':{'scaleX':1.10,'scaleY':.88,'translateY_face_units':-3},'left_bank':{'rotate_degrees':-8,'translateX_face_units':-4},'right_bank':{'rotate_degrees':8,'translateX_face_units':4},'instruction':'Support Mike four tilt mappings in existing prototype, not real-acceleration claims. Reuse canonical face, bounded eased blend .12-.20s and neutral return .30s. No new engine audio/long scene lock required for these continuous reactive poses. Code owns actual sensor calibration and mapping.'},'policy':'These are responsive micro-animations, NOT full costume scenes. No seven-second input lock. Release/cancel/hidden restores neutral. Preserve reduced-motion/static reactions and mute. Existing full-scene lock remains unchanged; do not let reactive input interrupt finite costume scenes.'}
(R/'reaction-timings.json').write_text(json.dumps(reactions,indent=2)+'\n')
manifest={'pack':'motion-buddy-touch-reactions-v2','owner_direction':'Interactive and fun companion; prioritise car mode, squishy petting, squeak/squish feedback and finger-following variety. Build into preview then adjust.','audio':records,'sound_policy':'SUPERSEDES old contact-loop instructions: no sustained curious_contact_loop/oooo loop. At most ONE selected finite sound per gesture; no pointermove retrigger, no stacked press+release, global minimum900ms spacing. Rotate short alternatives without immediate repeat. Sounds never block visual tracking/squish. Stop current sound immediately on mute/hidden/cancel.','source':'src/create_touch_patch.py; legacy_contact_generator_reference_only.py is provenance for copied cues, DO NOT run its main.','reaction_timings':'reaction-timings.json','ready_extra_scene_inventory':[{'name':'Astronaut, magician, bubble diver, disco','zip':'/workspace/motion-buddy-extra-scenes-v1-2026-11-06-spec-r1.zip','sha256':'70f16d66da575f6e90a9b4636e6567e9c454debbb1bcf5369da8547db384f23a'},{'name':'Japan','zip':'/workspace/motion-buddy-japan-scene-v1-2026-11-07-layout-r1.zip','sha256':'86b39456f222309793694e24dfaf681edada06b7542114910ed287b24b97948c'},{'name':'Australia revised art','zip':'/workspace/motion-buddy-australia-scene-v2-clean-art-2026-11-07.zip','sha256':'d497a151630aee674ad64d7a9461e7e3f50cdb63fd7d1908b76ea6ec876aeeed'}],'inventory_note':'Already delivered assets, not a claim of current app integration. Solance/Code should reuse any not yet surfaced before commissioning duplicates. Existing scene contracts retained.','qa':{'new_wav_headers_count_quantization_finite_headroom_zero_endpoints':'pass','three_legacy_cues_copied_byte_identical':'pass','no_external_downloads_or_repo_changes':True,'not_performed':['human listening','app integration/runtime','sensor/phone testing','deployment']}}
(R/'README.md').write_text('Small touch-reaction patch. Two new finite squish/spring sounds; three existing original squeak/chirp/wobble alternatives reused byte-for-byte. No contact sustain/oooo loop: ONE sound per gesture. reaction-timings.json gives short touch and car-pose targets, not app code or tested sensor behavior. Existing six scene assets listed for reuse. Source and float masters retained.\n')
manifest['files']={str(p.relative_to(R)):sha(p) for p in sorted(R.rglob('*')) if p.is_file() and p.name!='integration-manifest.json'};(R/'integration-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
zpath=R.with_suffix('.zip')
with zipfile.ZipFile(zpath,'w',zipfile.ZIP_DEFLATED) as z:
    for p in sorted(R.rglob('*')):
        if p.is_file():z.write(p,p.relative_to(R.parent))
with zipfile.ZipFile(zpath) as z:assert z.testzip() is None
assert all(sha(R/k)==v for k,v in manifest['files'].items())
print(json.dumps({'zip':str(zpath),'bytes':zpath.stat().st_size,'sha256':sha(zpath),'new_sounds':records[-2:],'qa':manifest['qa']},indent=2))
